let selected = 3, opened = false, sound = false, reduced = false, audio;
try { sound = localStorage.getItem('ds-sound') === 'true'; reduced = localStorage.getItem('ds-motion') === 'true'; } catch {}
function save(){try{localStorage.setItem('ds-sound',String(sound));localStorage.setItem('ds-motion',String(reduced));}catch{}}
function tone(launch=false){if(!sound)return;try{audio ??= new (window.AudioContext || window.webkitAudioContext)();audio.resume().catch(()=>{});const oscillator=audio.createOscillator(),gain=audio.createGain();oscillator.type='sine';oscillator.frequency.setValueAtTime(launch?660:520,audio.currentTime);oscillator.frequency.exponentialRampToValueAtTime(launch?990:780,audio.currentTime+.08);gain.gain.setValueAtTime(.035,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.14);oscillator.connect(gain);gain.connect(audio.destination);oscillator.start();oscillator.stop(audio.currentTime+.15);}catch{}}
function preferences(){document.body.classList.toggle('quiet',reduced);$('sound').textContent=`Sound: ${sound?'on':'off'}`;$('sound').setAttribute('aria-pressed',String(sound));if($('setting-sound')){$('setting-sound').lastElementChild.textContent=sound?'On':'Off';$('setting-sound').setAttribute('aria-pressed',String(sound));$('setting-motion').lastElementChild.textContent=reduced?'On':'Off';$('setting-motion').setAttribute('aria-pressed',String(reduced));}save();}
function toggleSound(){sound=!sound;preferences();tone();}
$('tile-track').innerHTML=apps.map((app,i)=>`<button class="tile" aria-label="${app.title}" aria-pressed="${i===0}" data-index="${i}"><span class="tile-icon"><svg viewBox="0 0 24 24" aria-hidden="true">${paths[app.id]}</svg></span><span class="tile-label">${app.title}</span></button>`).join('');
$('position-dots').innerHTML=apps.map(()=>'<span></span>').join('');
function position(){const tiles=$('tile-track').children;const step=tiles[1].offsetLeft-tiles[0].offsetLeft;$('tile-track').style.transform=`translateX(${-selected*step}px)`;document.querySelector('.carousel').scrollLeft=0;}
function select(index,beep=true){selected=Math.max(0,Math.min(apps.length-1,index));const app=apps[selected];$('selected-title').textContent=app.title;$('selected-subtitle').textContent=app.sub;$('preview-title').textContent=app.headline;$('preview-copy').textContent=app.copy;$('app-count').textContent=`${String(selected+1).padStart(2,'0')} / 07`;[...$('tile-track').children].forEach((tile,i)=>tile.setAttribute('aria-pressed',String(i===selected)));[...$('position-dots').children].forEach((dot,i)=>dot.classList.toggle('active',i===selected));$('previous').disabled=selected===0;$('next').disabled=selected===apps.length-1;position();if(beep)tone();}
function openApp(){if(opened)return;opened=true;const app=apps[selected];$('app-title').textContent=app.title;$('app-content').innerHTML=app.content;$('launcher').hidden=true;$('app-view').hidden=false;$('app-content').scrollTop=0;$('screen-hint').textContent='Press Escape or Home to return';$('app-title').focus();history.replaceState(null,'',`#${app.id}`);if(app.id==='settings'){$('setting-sound').onclick=toggleSound;$('setting-motion').onclick=()=>{reduced=!reduced;preferences();};preferences();}tone(true);}
function home(){if(!opened)return;opened=false;$('app-view').hidden=true;$('launcher').hidden=false;$('screen-hint').textContent='Choose an app to explore';history.replaceState(null,'',location.pathname+location.search);position();$('tile-track').children[selected].focus({preventScroll:true});tone();}
$('tile-track').addEventListener('click',event=>{const tile=event.target.closest('.tile');if(!tile)return;const i=Number(tile.dataset.index);if(i===selected)openApp();else select(i);});
$('previous').onclick=()=>select(selected-1);$('next').onclick=()=>select(selected+1);$('launch').onclick=openApp;$('back').onclick=home;$('home').onclick=home;$('sound').onclick=toggleSound;
document.addEventListener('keydown',event=>{if(event.altKey||event.metaKey||event.ctrlKey)return;if(event.key==='Escape'){home();return;}if(opened)return;if(['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();select(event.key==='Home'?0:event.key==='End'?apps.length-1:selected+(event.key==='ArrowRight'?1:-1));$('tile-track').children[selected].focus({preventScroll:true});}else if(event.key==='Enter'&&(event.target===document.body||event.target===$('launcher'))){event.preventDefault();openApp();}});
let pointerX=null;
const carousel=document.querySelector('.carousel');
carousel.addEventListener('pointerdown',event=>{pointerX=event.clientX;});
carousel.addEventListener('pointerup',event=>{if(pointerX===null)return;const dx=event.clientX-pointerX;pointerX=null;if(Math.abs(dx)>35){select(selected+(dx<0?1:-1));const suppress=e=>{e.preventDefault();e.stopPropagation();};carousel.addEventListener('click',suppress,{capture:true,once:true});setTimeout(()=>carousel.removeEventListener('click',suppress,true),0);}});
carousel.addEventListener('pointercancel',()=>{pointerX=null;});
window.addEventListener('resize',position);
function clock(){const now=new Date();$('clock').textContent=`${String(now.getMonth()+1).padStart(2,'0')}/${String(now.getDate()).padStart(2,'0')} ${now.toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',hour12:false})}`;$('clock').dateTime=now.toISOString();}
clock();setInterval(clock,30000);preferences();const initial=apps.findIndex(app=>`#${app.id}`===location.hash);select(initial>=0?initial:3,false);if(initial>=0)openApp();
